  75%      { transform: translate(12px, -30px); opacity: 1; box-shadow: 0 0 14px color-mix(in oklch, oklch(0.943 0.162 124.78) 100%, transparent); }
}

/* Rising Bubbles */
.roycss-particles-bubbles {
  position: relative;
