}

/* Scroll Driven Fade */
.roycss-scroll-driven-fade {
  animation: roy-scroll-fade linear both;
  animation-timeline: view();
  animation-range: entry 0% cover 40%;
}

@keyframes roy-scroll-fade {
  0% { opacity: 0; }
  100% { opacity: 1; }
}

@supports not (animation-timeline: view()) {
  .roycss-scroll-driven-fade {
    animation: roy-scroll-fade-fallback 2s ease-in-out infinite alternate;
  }
  @keyframes roy-scroll-fade-fallback {
    0% { opacity: 0; }
    100% { opacity: 1; }
  }
}

/* Scroll Driven Scale */
.roycss-scroll-driven-scale {
  animation: roy-scroll-scale linear both;
  animation-timeline: view();
  animation-range: entry 0% cover 50%;
}

@keyframes roy-scroll-scale {
  0% { transform: scale(0.6); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

@supports not (animation-timeline: view()) {
  .roycss-scroll-driven-scale {
    animation: roy-scroll-scale-fallback 2.4s ease-in-out infinite alternate;
  }
  @keyframes roy-scroll-scale-fallback {
    0% { transform: scale(0.6); opacity: 0.4; }
    100% { transform: scale(1); opacity: 1; }
  }
}

/* Scroll Driven Rotate */
.roycss-scroll-driven-rotate {
  animation: roy-scroll-rotate linear both;
  animation-timeline: view();
  animation-range: entry 0% exit 100%;
}

@keyframes roy-scroll-rotate {
  0% { transform: rotate(-45deg); }
  100% { transform: rotate(45deg); }
}

@supports not (animation-timeline: view()) {
  .roycss-scroll-driven-rotate {
    animation: roy-scroll-rotate-fallback 3s ease-in-out infinite alternate;
  }
  @keyframes roy-scroll-rotate-fallback {
    0% { transform: rotate(-45deg); }
    100% { transform: rotate(45deg); }
  }
}

/* Scroll Driven Translate */
.roycss-scroll-driven-translate {
  animation: roy-scroll-translate linear both;
  animation-timeline: view();
  animation-range: entry 0% cover 60%;
}

@keyframes roy-scroll-translate {
  0% { transform: translateX(-80px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}

@supports not (animation-timeline: view()) {
  .roycss-scroll-driven-translate {
    animation: roy-scroll-translate-fallback 2.5s ease-in-out infinite alternate;
  }
  @keyframes roy-scroll-translate-fallback {
    0% { transform: translateX(-80px); opacity: 0.4; }
    100% { transform: translateX(0); opacity: 1; }
  }
}

/* Scroll Driven Blur */
.roycss-scroll-driven-blur {
  animation: roy-scroll-blur linear both;
  animation-timeline: view();
  animation-range: entry 0% cover 50%;
}

@keyframes roy-scroll-blur {
  0% { filter: blur(12px); opacity: 0; transform: scale(1.05); }
  100% { filter: blur(0); opacity: 1; transform: scale(1); }
}

@supports not (animation-timeline: view()) {
  .roycss-scroll-driven-blur {
    animation: roy-scroll-blur-fallback 2.6s ease-in-out infinite alternate;
  }
  @keyframes roy-scroll-blur-fallback {
    0% { filter: blur(12px); opacity: 0.4; transform: scale(1.05); }
    100% { filter: blur(0); opacity: 1; transform: scale(1); }
  }
}

/* Scroll Driven Color */
.roycss-scroll-driven-color {
  animation: roy-scroll-color linear both;
  animation-timeline: view();
  animation-range: entry 0% exit 100%;
}

@keyframes roy-scroll-color {
  0% { background: oklch(0.567 0.159 275.21); color: oklch(1 0 89.88); }
  50% { background: oklch(0.606 0.219 292.72); color: oklch(1 0 89.88); }
  100% { background: oklch(0.656 0.212 354.31); color: oklch(1 0 89.88); }
}

@supports not (animation-timeline: view()) {
  .roycss-scroll-driven-color {
    animation: roy-scroll-color-fallback 4s ease-in-out infinite alternate;
  }
  @keyframes roy-scroll-color-fallback {
    0% { background: oklch(0.567 0.159 275.21); color: oklch(1 0 89.88); }
    50% { background: oklch(0.606 0.219 292.72); color: oklch(1 0 89.88); }
    100% { background: oklch(0.656 0.212 354.31); color: oklch(1 0 89.88); }
  }
}

/* Scroll Driven Sticky */
.roycss-scroll-driven-sticky {
  position: sticky;
  inset-block-start: 0;
  background: oklch(0.21 0.006 285.89);
  color: oklch(0.985 0 89.88);
  border: 1px solid oklch(0.274 0.005 286.03);
  border-radius: 8px;
  animation: roy-scroll-sticky linear both;
  animation-timeline: scroll(root);
  animation-range: 0 100px;
}

@keyframes roy-scroll-sticky {
  0% { box-shadow: 0 0 0 color-mix(in oklch, oklch(0 0 0) 0%, transparent); }
  100% { box-shadow: 0 8px 24px color-mix(in oklch, oklch(0 0 0) 40%, transparent); border-color: oklch(0.37 0.012 285.81); }
}

@supports not (animation-timeline: scroll()) {
  .roycss-scroll-driven-sticky {
    animation: roy-scroll-sticky-fallback 2s ease-in-out infinite alternate;
  }
  @keyframes roy-scroll-sticky-fallback {
    0% { box-shadow: 0 0 0 color-mix(in oklch, oklch(0 0 0) 0%, transparent); border-color: oklch(0.274 0.005 286.03); }
    100% { box-shadow: 0 8px 24px color-mix(in oklch, oklch(0 0 0) 40%, transparent); border-color: oklch(0.37 0.012 285.81); }
  }
}

/* Scroll Driven Progress Ring */
.roycss-scroll-driven-progress-ring {
  position: relative;
  border-radius: 50%;
  background:
    conic-gradient(oklch(0.567 0.159 275.21) 0deg, oklch(0.567 0.159 275.21) 0deg, oklch(0.274 0.005 286.03) 0deg, oklch(0.274 0.005 286.03) 360deg);
  animation: roy-scroll-ring linear both;
  animation-timeline: scroll(root);
  animation-range: 0 100%;
}
.roycss-scroll-driven-progress-ring::after {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: oklch(0.145 0.002 286.13);
}

@keyframes roy-scroll-ring {
  0% {
    background:
      conic-gradient(oklch(0.567 0.159 275.21) 0deg, oklch(0.567 0.159 275.21) 0deg, oklch(0.274 0.005 286.03) 0deg, oklch(0.274 0.005 286.03) 360deg);
  }
  100% {
    background:
      conic-gradient(oklch(0.567 0.159 275.21) 0deg, oklch(0.567 0.159 275.21) 360deg, oklch(0.274 0.005 286.03) 360deg, oklch(0.274 0.005 286.03) 360deg);
  }
}

@supports not (animation-timeline: scroll()) {
  .roycss-scroll-driven-progress-ring {
    animation: roy-scroll-ring-fallback 2s linear infinite alternate;
  }
  @keyframes roy-scroll-ring-fallback {
    0% {
      background:
        conic-gradient(oklch(0.567 0.159 275.21) 0deg, oklch(0.567 0.159 275.21) 0deg, oklch(0.274 0.005 286.03) 0deg, oklch(0.274 0.005 286.03) 360deg);
    }
    100% {
      background:
        conic-gradient(oklch(0.567 0.159 275.21) 0deg, oklch(0.567 0.159 275.21) 360deg, oklch(0.274 0.005 286.03) 360deg, oklch(0.274 0.005 286.03) 360deg);
    }
  }
}

/* Anchor Tooltip — CSS Anchor Positioning API */
.roycss-anchor-tooltip {
  position: relative;
  inline-size: 220px;
  block-size: 140px;
  border-radius: 14px;
  background: linear-gradient(135deg, oklch(0.208 0.04 265.75), oklch(0.279 0.037 260.03));
  display: grid;
  place-items: center;
  anchor-name: --roy-at-host;
}
.roycss-anchor-tooltip > span {
  color: oklch(0.929 0.013 255.51);
  font: 600 14px/1 system-ui, sans-serif;
  padding: 8px 16px;
  border-radius: 8px;
  background: color-mix(in oklch, oklch(0.696 0.149 162.48) 15%, transparent);
  border: 1px solid color-mix(in oklch, oklch(0.696 0.149 162.48) 40%, transparent);
  anchor-name: --roy-at-btn;
}
.roycss-anchor-tooltip::after {
  content: "Anchored tooltip ✓";
  position: absolute;
  position-anchor: --roy-at-btn;
  position-area: block-end span-inline-end;
  margin-block-end: 8px;
  padding: 6px 10px;
  border-radius: 6px;
  background: oklch(0.696 0.149 162.48);
  color: oklch(0.262 0.049 172.55);
  font: 600 12px/1.2 system-ui, sans-serif;
  white-space: nowrap;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.2s, transform 0.2s;
  pointer-events: none;
}
.roycss-anchor-tooltip:hover::after,
.roycss-anchor-tooltip:focus-within::after {
  opacity: 1;
  transform: translateY(0);
}
/* Fallback: browsers without anchor positioning stack the tooltip below */
@supports not (position-anchor: --x) {
  .roycss-anchor-tooltip::after {
    position: absolute;
    inset-block-end: 8px;
    inset-inline-start: 50%;
    transform: translate(-50%, 4px);
  }
  .roycss-anchor-tooltip:hover::after,
  .roycss-anchor-tooltip:focus-within::after {
    transform: translate(-50%, 0);
  }
}

/* Has Parent Highlight — :has() relational selector */
.roycss-has-parent-highlight {
  inline-size: 220px;
  padding: 18px;
  border-radius: 14px;
  background: oklch(0.279 0.037 260.03);
  border: 2px solid oklch(0.372 0.039 257.29);
  transition: border-color 0.25s, box-shadow 0.25s, background 0.25s;
}
.roycss-has-parent-highlight > span {
  display: block;
  inline-size: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  background: oklch(0.208 0.04 265.75);
  color: oklch(0.869 0.02 252.89);
  font: 500 13px/1.4 system-ui, sans-serif;
  outline: none;
  border: 1px solid oklch(0.446 0.037 257.28);
  transition: border-color 0.25s, color 0.25s;
}
/* When the inner span is hovered/focused, the PARENT card reacts */
.roycss-has-parent-highlight:has(> span:hover) {
  border-color: oklch(0.696 0.149 162.48);
  box-shadow: 0 0 0 4px color-mix(in oklch, oklch(0.696 0.149 162.48) 18%, transparent);
  background: oklch(0.261 0.036 174.14);
}
.roycss-has-parent-highlight:has(> span:focus-visible) {
  border-color: oklch(0.769 0.165 70.08);
  box-shadow: 0 0 0 4px color-mix(in oklch, oklch(0.769 0.165 70.08) 20%, transparent);
}
.roycss-has-parent-highlight:has(> span:hover) > span {
  color: oklch(0.773 0.153 163.22);
  border-color: oklch(0.696 0.149 162.48);
}
/* Fallback for browsers without :has() — child still gets focus ring */
@supports not selector(:has(*)) {
  .roycss-has-parent-highlight > span:focus-visible {
    border-color: oklch(0.696 0.149 162.48);
    box-shadow: 0 0 0 3px color-mix(in oklch, oklch(0.696 0.149 162.48) 25%, transparent);
  }
}

/* Container Query Card — @container queries */
.roycss-container-query-card {
  container-type: inline-size;
  container-name: roycq;
  inline-size: 100%;
  max-inline-size: 360px;
  block-size: 160px;
  border-radius: 14px;
  background: linear-gradient(135deg, oklch(0.359 0.135 278.7), oklch(0.38 0.178 293.74));
  padding: 14px;
  display: grid;
  gap: 10px;
  grid-template-columns: 1fr;
  align-content: center;
  color: oklch(0.943 0.028 294.59);
  font: 500 12px/1.4 system-ui, sans-serif;
  transition: grid-template-columns 0.3s;
}
.roycss-container-query-card > span {
  display: block;
  padding: 8px 10px;
  border-radius: 8px;
  background: color-mix(in oklch, oklch(1 0 89.88) 10%, transparent);
  border: 1px solid color-mix(in oklch, oklch(1 0 89.88) 18%, transparent);
}
.roycss-container-query-card::before {
  content: "📐 narrow";
  font-weight: 700;
  color: oklch(0.811 0.101 293.57);
}
/* Wide container → side-by-side columns */
@container roycq (min-inline-size: 240px) {
  .roycss-container-query-card {
    grid-template-columns: 1fr 1fr;
  }
  .roycss-container-query-card::before {
    content: "📐 wide";
    grid-column: 1 / -1;
    color: oklch(0.905 0.089 164.15);
  }
}
@container roycq (min-inline-size: 320px) {
  .roycss-container-query-card {
    grid-template-columns: repeat(3, 1fr);
  }
  .roycss-container-query-card::before {
    content: "📐 extra-wide";
    color: oklch(0.924 0.115 95.75);
  }
}
/* Fallback: container query unsupported → use media-query-ish default */
@supports not (container-type: inline-size) {
  .roycss-container-query-card {
    grid-template-columns: 1fr 1fr;
  }
}

/* Starting Style Fade — @starting-style for first-render transition */
.roycss-starting-style-fade {
  inline-size: 200px;
  block-size: 120px;
  border-radius: 14px;
  background: linear-gradient(135deg, oklch(0.592 0.218 0.58), oklch(0.558 0.252 302.32));
  display: grid;
  place-items: center;
  color: oklch(1 0 89.88);
  font: 700 14px/1 system-ui, sans-serif;
  letter-spacing: 0.15em;
  opacity: 1;
  transform: translateY(0) scale(1);
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
  /* Restart the entry on every hover-out for demo purposes */
  animation: roy-b10-ss-restart 3s ease-in-out infinite;
}
@keyframes roy-b10-ss-restart {
  0%, 40%   { opacity: 1; transform: translateY(0) scale(1); }
  50%       { opacity: 0; transform: translateY(20px) scale(0.92); }
  60%, 100% { opacity: 1; transform: translateY(0) scale(1); }
}
/* The actual @starting-style rule (applied on the very first frame
   of the element appearing in the DOM) */
@starting-style {
  .roycss-starting-style-fade {
    opacity: 0;
    transform: translateY(24px) scale(0.9);
  }
}
/* Fallback: if @starting-style is unsupported, the animation alone
   still demonstrates the fade-in behavior. */
@supports not (animation-timeline: --fake) {
  /* no-op — modern browsers handle @starting-style natively */
}

/* Auto Height Expand — interpolate-size: allow-keywords */
.roycss-auto-height-expand {
  interpolate-size: allow-keywords;
  inline-size: 220px;
  border-radius: 14px;
  background: oklch(0.208 0.04 265.75);
  padding: 12px 14px;
  color: oklch(0.929 0.013 255.51);
  font: 500 12px/1.4 system-ui, sans-serif;
  overflow: hidden;
}
.roycss-auto-height-expand > span {
  display: block;
  font-weight: 700;
  color: oklch(0.773 0.153 163.22);
  cursor: pointer;
  padding-block-end: 6px;
}
.roycss-auto-height-expand::after {
  content: "This hidden paragraph smoothly grows to its natural block-size: auto using the new interpolate-size property. No max-height hacks required — the browser can now interpolate to the auto keyword directly.";
  display: block;
  block-size: 0;
  opacity: 0;
  overflow: hidden;
  transition: height 0.4s ease, opacity 0.4s ease;
  color: oklch(0.711 0.035 256.79);
  font-size: 11px;
}
.roycss-auto-height-expand:hover::after {
  block-size: auto;
  opacity: 1;
}
/* Fallback for browsers without interpolate-size — use max-height */
@supports not (interpolate-size: allow-keywords) {
  .roycss-auto-height-expand::after {
    transition: max-height 0.4s ease, opacity 0.4s ease;
    max-block-size: 0;
  }
  .roycss-auto-height-expand:hover::after {
    max-block-size: 200px;
    block-size: auto;
  }
}

/* View Transition Snapshot — view-transition-name */
.roycss-view-transition-snapshot {
  inline-size: 200px;
  block-size: 120px;
  border-radius: 16px;
  background: linear-gradient(135deg, oklch(0.685 0.148 237.32), oklch(0.585 0.204 277.12));
  display: grid;
  place-items: center;
  color: oklch(1 0 89.88);
  font: 700 14px/1 system-ui, sans-serif;
  view-transition-name: roy-vt-card;
  animation: roy-b10-vt-morph 4s ease-in-out infinite;
}
/* ::view-transition-group pseudo for cross-snapshot morph */
::view-transition-group(roy-vt-card) {
  animation-duration: 0.6s;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}
::view-transition-old(roy-vt-card) {
  animation: roy-b10-vt-out 0.4s ease forwards;
}
::view-transition-new(roy-vt-card) {
  animation: roy-b10-vt-in 0.4s ease forwards;
}
@keyframes roy-b10-vt-morph {
  0%, 35%   { border-radius: 16px; background: linear-gradient(135deg, oklch(0.685 0.148 237.32), oklch(0.585 0.204 277.12)); }
  50%, 85%  { border-radius: 60px; background: linear-gradient(135deg, oklch(0.645 0.215 16.44), oklch(0.769 0.165 70.08)); }
  100%      { border-radius: 16px; background: linear-gradient(135deg, oklch(0.685 0.148 237.32), oklch(0.585 0.204 277.12)); }
}
@keyframes roy-b10-vt-out {
  to { opacity: 0; transform: scale(1.05); }
}
@keyframes roy-b10-vt-in {
  from { opacity: 0; transform: scale(0.95); }
}
/* Fallback: if View Transitions unsupported, the morph animation alone
   still demonstrates the visual transition. */
@supports not (view-transition-name: none) {
  /* morph animation above already covers the visual demo */
}

/* Balanced Text — text-wrap: balance & pretty */
.roycss-balanced-text {
  inline-size: 240px;
