  40%, 85%  { transform: scale(1); opacity: 1; }
  100%      { transform: scale(0.3); opacity: 0; }
}
@keyframes roy-b12-context-hint {
  0%, 25%   { opacity: 1; }
  40%, 100% { opacity: 0.3; }
}

/* Hypnotic Infinite-Zoom Spiral */
.roycss-hypnotic-spiral {
