  border-radius: 50%;
  box-shadow: 0 0 14px color-mix(in oklch, oklch(0.721 0.187 47.68) 90%, transparent), 0 0 28px color-mix(in oklch, oklch(0.653 0.235 33.88) 60%, transparent);
  animation: roy-b15-projectile-fly 1.6s ease-in-out infinite;
}
.roycss-game-projectile::before {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-end: 50%;
  inline-size: 50px;
  block-size: 4px;
  transform: translateY(-50%);
  background: linear-gradient(to left, color-mix(in oklch, oklch(0.822 0.154 74.42) 90%, transparent) 0%, color-mix(in oklch, oklch(0.671 0.221 37.64) 60%, transparent) 40%, transparent 100%);
  border-radius: 4px;
  filter: blur(1px);
}
.roycss-game-projectile::after {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-end: 60%;
  inline-size: 6px;
  block-size: 6px;
  transform: translateY(-50%);
  background: oklch(0.913 0.121 91.98);
  border-radius: 50%;
  box-shadow: -8px 2px 0 -1px color-mix(in oklch, oklch(0.785 0.165 65.58) 70%, transparent), -16px -2px 0 -2px color-mix(in oklch, oklch(0.693 0.206 42.88) 50%, transparent), -24px 4px 0 -3px color-mix(in oklch, oklch(0.653 0.235 33.88) 30%, transparent);
}
@keyframes roy-b15-projectile-fly {
  0% { transform: translateX(-60px) scale(0.9); }
  50% { transform: translateX(60px) scale(1.05); }
  100% { transform: translateX(-60px) scale(0.9); }
}

/* Game Explosion */
.roycss-game-explosion {
  inline-size: 50px;
  block-size: 50px;
  position: relative;
}
.roycss-game-explosion::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle, oklch(1 0 89.88) 0%, oklch(0.907 0.17 97.66) 25%, oklch(0.689 0.206 39.23) 55%, oklch(0.512 0.204 30.22) 80%, transparent 100%);
  border-radius: 50%;
  box-shadow: 0 0 20px color-mix(in oklch, oklch(0.721 0.187 47.68) 90%, transparent), 0 0 40px color-mix(in oklch, oklch(0.653 0.235 33.88) 60%, transparent);
  animation: roy-b15-explosion-core 1s ease-out infinite;
}
.roycss-game-explosion::after {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  inline-size: 8px;
  block-size: 8px;
  transform: translate(-50%, -50%);
  background: transparent;
  border-radius: 50%;
  box-shadow:
    -28px -18px 0 -2px oklch(0.733 0.182 50.75),
    28px -18px 0 -2px oklch(0.733 0.182 50.75),
    -28px 18px 0 -2px oklch(0.733 0.182 50.75),
    28px 18px 0 -2px oklch(0.733 0.182 50.75),
    -34px 0 0 -3px oklch(0.549 0.174 39.51),
    34px 0 0 -3px oklch(0.549 0.174 39.51),
    0 -30px 0 -2px oklch(0.689 0.206 39.23),
    0 30px 0 -2px oklch(0.689 0.206 39.23);
  animation: roy-b15-explosion-debris 1s ease-out infinite;
}
@keyframes roy-b15-explosion-core {
  0% { transform: scale(0.3); opacity: 1; }
  50% { transform: scale(1.2); opacity: 1; }
  100% { transform: scale(1.6); opacity: 0; }
}
@keyframes roy-b15-explosion-debris {
  0% { transform: translate(-50%, -50%) scale(0.5); opacity: 1; }
  100% { transform: translate(-50%, -50%) scale(1.6); opacity: 0; }
}

/* Game Level Up */
.roycss-game-level-up {
  inline-size: 60px;
  block-size: 60px;
  position: relative;
}
.roycss-game-level-up::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(circle, oklch(1 0 89.88) 0%, oklch(0.913 0.121 91.98) 30%, oklch(0.813 0.165 75.04) 60%, transparent 100%);
  box-shadow: 0 0 30px color-mix(in oklch, oklch(0.9 0.157 94.82) 90%, transparent);
  animation: roy-b15-levelup-core 1.4s ease-out infinite;
}
.roycss-game-level-up::after {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  inline-size: 16px;
  block-size: 16px;
  transform: translate(-50%, -50%);
  border: 2px solid color-mix(in oklch, oklch(0.9 0.157 94.82) 80%, transparent);
  border-radius: 50%;
  box-shadow: 0 0 8px color-mix(in oklch, oklch(0.9 0.157 94.82) 60%, transparent);
  animation: roy-b15-levelup-ring 1.4s ease-out infinite;
}
@keyframes roy-b15-levelup-core {
  0% { transform: scale(0.4); opacity: 1; }
  40% { transform: scale(1); opacity: 1; }
  100% { transform: scale(1.3); opacity: 0; }
}
@keyframes roy-b15-levelup-ring {
  0% { transform: translate(-50%, -50%) scale(0.5); opacity: 1; border-inline-size: 3px; }
  100% { transform: translate(-50%, -50%) scale(4); opacity: 0; border-inline-size: 1px; }
}

/* Game Screen Shake */
.roycss-game-screen-shake {
  inline-size: 100px;
  block-size: 70px;
  position: relative;
  background: linear-gradient(135deg, oklch(0.308 0.064 257.75) 0%, oklch(0.212 0.051 260.48) 100%);
  border: 2px solid oklch(0.53 0.066 244.92);
  border-radius: 4px;
  box-shadow: 0 0 0 1px oklch(0.144 0.024 260.16), 0 6px 14px color-mix(in oklch, oklch(0 0 0) 50%, transparent);
  animation: roy-b15-screen-shake 0.4s linear infinite;
}
.roycss-game-screen-shake::before {
  content: "HIT!";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  transform: translate(-50%, -50%);
  color: oklch(0.66 0.227 26.03);
  font-family: "Impact", "Arial Black", sans-serif;
  font-size: 22px;
  font-weight: 900;
  letter-spacing: 2px;
  text-shadow:
    -1px -1px 0 oklch(0 0 0), 1px -1px 0 oklch(0 0 0),
    -1px 1px 0 oklch(0 0 0), 1px 1px 0 oklch(0 0 0),
    0 0 8px color-mix(in oklch, oklch(0.656 0.23 26.33) 90%, transparent);
  animation: roy-b15-screen-flash 0.2s steps(2) infinite;
}
.roycss-game-screen-shake::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 4px;
  box-shadow: inset 0 0 14px color-mix(in oklch, oklch(0.656 0.23 26.33) 50%, transparent);
  animation: roy-b15-screen-glow 0.4s ease-in-out infinite;
}
@keyframes roy-b15-screen-shake {
  0% { transform: translate(0, 0); }
  20% { transform: translate(-3px, 2px); }
  40% { transform: translate(3px, -2px); }
  60% { transform: translate(-2px, -3px); }
  80% { transform: translate(2px, 3px); }
  100% { transform: translate(0, 0); }
}
@keyframes roy-b15-screen-flash {
  0% { opacity: 1; }
  100% { opacity: 0.5; }
}
@keyframes roy-b15-screen-glow {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 1; }
}

/* Game Loading Bar */
.roycss-game-loading-bar {
  inline-size: 160px;
  block-size: 22px;
  background: oklch(0.167 0.034 53.76);
  border: 3px solid oklch(0.413 0.084 64.27);
  border-radius: 3px;
  overflow: hidden;
  position: relative;
  box-shadow: inset 0 2px 4px color-mix(in oklch, oklch(0 0 0) 80%, transparent), 0 0 0 1px oklch(0.219 0.045 55.68);
}
.roycss-game-loading-bar::before {
  content: "";
  position: absolute;
  inset-block-start: 2px;
  inset-block-end: 2px;
  inset-inline-start: 2px;
  inline-size: 70%;
  background:
    repeating-linear-gradient(90deg, oklch(0.813 0.165 75.04) 0, oklch(0.813 0.165 75.04) 14px, oklch(0.571 0.132 57.4) 14px, oklch(0.571 0.132 57.4) 16px);
  border-radius: 2px;
  box-shadow: 0 0 8px color-mix(in oklch, oklch(0.821 0.163 76.61) 80%, transparent), inset 0 1px 0 color-mix(in oklch, oklch(0.953 0.078 95.74) 70%, transparent);
  animation: roy-b15-loading-fill 2s ease-in-out infinite;
}
.roycss-game-loading-bar::after {
  content: "";
  position: absolute;
  inset-block-start: 2px;
  inset-block-end: 2px;
  inset-inline-end: 2px;
  inline-size: 4px;
  background: oklch(0.913 0.121 91.98);
  box-shadow: 0 0 10px color-mix(in oklch, oklch(0.944 0.142 102.24) 100%, transparent), 0 0 20px color-mix(in oklch, oklch(0.858 0.167 87.29) 70%, transparent);
  animation: roy-b15-loading-edge 2s ease-in-out infinite;
}
@keyframes roy-b15-loading-fill {
  0% { inline-size: 5%; }
  50% { inline-size: 75%; }
  100% { inline-size: 5%; }
}
@keyframes roy-b15-loading-edge {
  0% { inset-inline-end: 80%; opacity: 0.8; }
  50% { inset-inline-end: 8%; opacity: 1; }
  100% { inset-inline-end: 80%; opacity: 0.8; }
}

/* Game Cursor Blink */
.roycss-game-cursor-blink {
  font-family: "Courier New", monospace;
  font-size: 22px;
  font-weight: 700;
  color: oklch(0.872 0.255 147.64);
  letter-spacing: 1px;
  text-shadow: 0 0 8px color-mix(in oklch, oklch(0.872 0.256 147.41) 80%, transparent), 0 0 14px color-mix(in oklch, oklch(0.872 0.256 147.41) 40%, transparent);
  position: relative;
  padding-inline-end: 14px;
}
.roycss-game-cursor-blink::after {
  content: "_";
  position: absolute;
  inset-inline-end: 0;
  inset-block-start: 50%;
  transform: translateY(-50%);
  color: oklch(0.872 0.255 147.64);
  text-shadow: 0 0 8px color-mix(in oklch, oklch(0.872 0.256 147.41) 90%, transparent);
  animation: roy-b15-cursor-blink 1s steps(2) infinite;
}
@keyframes roy-b15-cursor-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

/* Game Float Bobble */
.roycss-game-float-bobble {
  inline-size: 50px;
  block-size: 50px;
  position: relative;
  background: radial-gradient(circle at 35% 30%, oklch(0.904 0.173 149.93) 0%, oklch(0.716 0.176 148.21) 50%, oklch(0.53 0.131 149.95) 100%);
  border-radius: 50%;
  box-shadow: inset 0 4px 0 color-mix(in oklch, oklch(1 0 89.88) 40%, transparent), inset 0 -6px 10px color-mix(in oklch, oklch(0.309 0.105 142.5) 60%, transparent), 0 0 14px color-mix(in oklch, oklch(0.793 0.202 145.82) 60%, transparent);
  animation: roy-b15-float-bob 2.4s ease-in-out infinite;
}
.roycss-game-float-bobble::before {
  content: "";
  position: absolute;
  inset-block-start: 22%;
  inset-inline-start: 28%;
  inline-size: 12px;
  block-size: 12px;
  background: color-mix(in oklch, oklch(1 0 89.88) 70%, transparent);
  border-radius: 50%;
  filter: blur(1px);
}
.roycss-game-float-bobble::after {
  content: "";
  position: absolute;
  inset-block-end: -16px;
  inset-inline-start: -10px;
  inset-inline-end: -10px;
  block-size: 8px;
  background: radial-gradient(ellipse, color-mix(in oklch, oklch(0 0 0) 50%, transparent) 0%, transparent 70%);
  animation: roy-b15-float-shadow 2.4s ease-in-out infinite;
}
@keyframes roy-b15-float-bob {
  0%, 100% { transform: translateY(0) rotate(-4deg); }
  50% { transform: translateY(-14px) rotate(4deg); }
}
@keyframes roy-b15-float-shadow {
  0%, 100% { transform: scaleX(1); opacity: 0.5; }
  50% { transform: scaleX(0.6); opacity: 0.25; }
}

/* Spring Physics Bounce */
.roycss-spring-physics-bounce {
  inline-size: 80px;
  block-size: 80px;
  border-radius: 20px;
  background: linear-gradient(135deg, oklch(0.78 0.20 145), oklch(0.60 0.22 170));
  box-shadow:
    inset 0 2px 0 oklch(1 0 0 / 0.4),
    0 10px 20px -6px oklch(0.4 0.18 160 / 0.5);
  animation: roy-b16-spring-bounce 2.4s cubic-bezier(0.5, 1.6, 0.4, 0.95) infinite;
  transform-origin: center bottom;
}
@keyframes roy-b16-spring-bounce {
  0%   { transform: translateY(-120px) scaleY(0.7); opacity: 0; }
  40%  { transform: translateY(0) scaleY(1.15); opacity: 1; }
  55%  { transform: translateY(0) scaleY(0.85); }
  70%  { transform: translateY(0) scaleY(1.05); }
  85%  { transform: translateY(0) scaleY(0.97); }
  100% { transform: translateY(-120px) scaleY(0.7); opacity: 0; }
}

/* Gravity Drop */
.roycss-gravity-drop {
  inline-size: 64px;
  block-size: 64px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, oklch(0.88 0.18 50), oklch(0.65 0.22 30));
  box-shadow:
    inset -4px -6px 8px oklch(0 0 0 / 0.2),
    0 8px 14px -4px oklch(0.4 0.18 40 / 0.55);
  animation:
    roy-b16-grav-fall 2s cubic-bezier(0.6, 0, 0.9, 0.3) infinite,
    roy-b16-grav-squash 2s cubic-bezier(0.3, 1.4, 0.6, 1) infinite;
}
@keyframes roy-b16-grav-fall {
  0%   { transform: translateY(-100px); }
  60%  { transform: translateY(0); }
  100% { transform: translateY(-100px); }
}
@keyframes roy-b16-grav-squash {
  0%   { transform: scale(1, 1); }
  55%  { transform: scale(1, 1); }
  60%  { transform: scale(1.4, 0.6); }
  66%  { transform: scale(0.85, 1.15); }
  72%  { transform: scale(1.05, 0.95); }
  78%  { transform: scale(1, 1); }
  100% { transform: scale(1, 1); }
}

/* Momentum Scroll */
.roycss-momentum-scroll {
  inline-size: 280px;
  block-size: 80px;
  position: relative;
  overflow: hidden;
  border-radius: 12px;
  background: linear-gradient(180deg, oklch(0.16 0.02 260), oklch(0.10 0.02 260));
  box-shadow: inset 0 0 0 1px oklch(1 0 0 / 0.06), inset 0 2px 6px oklch(0 0 0 / 0.5);
}
.roycss-momentum-scroll::before {
  /* scrolling content strip */
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inline-size: 60%;
  block-size: 14px;
  transform: translateY(-50%);
  background: linear-gradient(90deg, transparent, oklch(0.78 0.20 200), oklch(0.85 0.18 250), transparent);
  border-radius: 7px;
  filter: drop-shadow(0 0 8px oklch(0.78 0.20 200 / 0.6));
  animation: roy-b16-momentum 3.2s cubic-bezier(0.2, 0.8, 0.2, 1) infinite;
}
.roycss-momentum-scroll::after {
  /* edge fade mask feel — vignette */
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, oklch(0.10 0.02 260) 0%, transparent 12%, transparent 88%, oklch(0.10 0.02 260) 100%);
  pointer-events: none;
}
@keyframes roy-b16-momentum {
  0%   { transform: translate(-70%, -50%) translateX(0); }
  45%  { transform: translate(60%, -50%) translateX(0); }
  55%  { transform: translate(60%, -50%) translateX(0); }
  100% { transform: translate(280%, -50%) translateX(0); }
}

/* Kinetic Typography */
.roycss-kinetic-typography {
  font-family: "Inter", "Segoe UI", system-ui, sans-serif;
  font-size: 56px;
  font-weight: 400;
  font-stretch: 100%;
  font-variation-settings: "wght" 400, "wdth" 100;
  background: linear-gradient(135deg, oklch(0.85 0.18 280), oklch(0.78 0.22 200));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  letter-spacing: 0.04em;
  animation:
    roy-b16-kinetic-weight 3.6s ease-in-out infinite,
    roy-b16-kinetic-width 5s ease-in-out infinite;
  filter: drop-shadow(0 4px 14px oklch(0.5 0.18 270 / 0.4));
}
@keyframes roy-b16-kinetic-weight {
  0%, 100% { font-variation-settings: "wght" 300, "wdth" 100; font-weight: 300; }
  50%      { font-variation-settings: "wght" 800, "wdth" 100; font-weight: 800; }
}
@keyframes roy-b16-kinetic-width {
  0%, 100% { font-stretch: 85%;  letter-spacing: 0.02em; }
  50%      { font-stretch: 115%; letter-spacing: 0.08em; }
}

/* Morph Shape Cycle */
.roycss-morph-shape-cycle {
  inline-size: 160px;
  block-size: 160px;
  background:
    linear-gradient(135deg, oklch(0.82 0.22 320), oklch(0.65 0.25 270));
  box-shadow: 0 12px 30px -8px oklch(0.45 0.2 300 / 0.5);
  animation: roy-b16-morph-cycle 8s ease-in-out infinite;
  transform-origin: center;
}
@keyframes roy-b16-morph-cycle {
  0%, 100% {
    clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
    border-radius: 0;
    transform: rotate(0deg) scale(1);
  }
  20% {
    clip-path: polygon(50% 0%, 95% 25%, 95% 75%, 50% 100%, 5% 75%, 5% 25%);
    border-radius: 12px;
    transform: rotate(36deg) scale(0.95);
  }
  40% {
    clip-path: polygon(50% 0%, 80% 10%, 100% 50%, 80% 90%, 50% 100%, 20% 90%, 0% 50%, 20% 10%);
    border-radius: 30%;
    transform: rotate(72deg) scale(1.05);
  }
  60% {
    clip-path: polygon(50% 0%, 90% 50%, 50% 100%, 10% 50%);
    border-radius: 0;
    transform: rotate(108deg) scale(0.95);
  }
  80% {
    clip-path: polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%);
    border-radius: 50%;
    transform: rotate(144deg) scale(1);
  }
}

/* Parallax Depth Scroll — uses scroll-driven animation timeline */
.roycss-parallax-depth-scroll {
  inline-size: 280px;
  block-size: 180px;
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  background: linear-gradient(180deg, oklch(0.18 0.08 260), oklch(0.10 0.05 270));
  isolation: isolate;
}
.roycss-parallax-depth-scroll::before,
.roycss-parallax-depth-scroll::after {
  content: "";
  position: absolute;
  inset-block-start: 0;
  inset-inline: -20%;
  pointer-events: none;
}
.roycss-parallax-depth-scroll::before {
  /* mid layer — mountains */
  block-size: 70%;
  inset-block-start: 30%;
  background:
    linear-gradient(180deg, transparent, oklch(0.3 0.10 270 / 0.9)),
    conic-gradient(from 0deg at 50% 100%, oklch(0.35 0.10 270) 0deg, transparent 60deg, oklch(0.35 0.10 270) 120deg, transparent 180deg, oklch(0.35 0.10 270) 240deg, transparent 300deg);
  background-size: 50% 100%, 100% 100%;
  background-repeat: repeat-x, no-repeat;
  animation: roy-b16-parallax-mid linear both;
  animation-timeline: view();
}
.roycss-parallax-depth-scroll::after {
  /* near layer — stars / foreground particles */
  block-size: 100%;
  background-image:
    radial-gradient(circle, oklch(1 0 0 / 0.9) 1px, transparent 1.5px),
    radial-gradient(circle, oklch(0.85 0.18 280 / 0.7) 1px, transparent 1.5px);
  background-size: 40px 40px, 70px 70px;
  background-position: 0 0, 20px 30px;
  animation: roy-b16-parallax-near linear both;
  animation-timeline: view();
}
@keyframes roy-b16-parallax-mid {
  from { transform: translateX(-10%); opacity: 0.5; }
  to   { transform: translateX(10%);  opacity: 1; }
}
@keyframes roy-b16-parallax-near {
  from { transform: translateX(20%); }
  to   { transform: translateX(-20%); }
}

/* Elastic Snap */
.roycss-elastic-snap {
  inline-size: 90px;
  block-size: 90px;
  border-radius: 24px;
  background: linear-gradient(135deg, oklch(0.80 0.22 280), oklch(0.65 0.20 320));
  box-shadow:
    inset 0 2px 0 oklch(1 0 0 / 0.35),
    0 12px 22px -8px oklch(0.4 0.18 300 / 0.55);
  animation: roy-b16-elastic 2.6s cubic-bezier(0.68, -0.55, 0.265, 1.55) infinite;
}
@keyframes roy-b16-elastic {
  0%   { transform: translateX(-90px) scale(0.85); opacity: 0; }
  20%  { transform: translateX(0) scale(1.1); opacity: 1; }
  30%  { transform: translateX(28px) scale(0.96); }
  40%  { transform: translateX(-16px) scale(1.04); }
  50%  { transform: translateX(10px) scale(0.98); }
  60%  { transform: translateX(-5px) scale(1.01); }
  70%  { transform: translateX(0) scale(1); }
  85%  { transform: translateX(0) scale(1); opacity: 1; }
  100% { transform: translateX(-90px) scale(0.85); opacity: 0; }
}

/* Fluid Motion Path */
.roycss-fluid-motion {
  inline-size: 280px;
  block-size: 160px;
  position: relative;
  overflow: hidden;
  border-radius: 14px;
  background: linear-gradient(160deg, oklch(0.92 0.04 230), oklch(0.82 0.06 200));
  box-shadow: inset 0 0 0 1px oklch(0.4 0.04 240 / 0.15);
}
.roycss-fluid-motion::before,
.roycss-fluid-motion::after {
  content: "";
  position: absolute;
  inline-size: 28px;
  block-size: 28px;
  border-radius: 50%;
  pointer-events: none;
}
.roycss-fluid-motion::before {
  background: radial-gradient(circle at 35% 35%, oklch(0.85 0.22 280), oklch(0.65 0.24 260));
  box-shadow: 0 0 20px oklch(0.7 0.22 280 / 0.6);
  offset-path: path("M -20,80 C 60,20 120,140 200,60 S 320,100 300,80");
  offset-rotate: 0deg;
  animation: roy-b16-fluid-path 4.5s ease-in-out infinite;
}
.roycss-fluid-motion::after {
  background: radial-gradient(circle at 35% 35%, oklch(0.85 0.22 200), oklch(0.65 0.24 220));
  box-shadow: 0 0 20px oklch(0.7 0.22 200 / 0.6);
  offset-path: path("M -20,60 C 60,120 120,20 200,100 S 320,60 300,60");
  offset-rotate: 0deg;
  animation: roy-b16-fluid-path 5.5s ease-in-out infinite reverse;
  inline-size: 20px;
  block-size: 20px;
}
@keyframes roy-b16-fluid-path {
  0%   { offset-distance: 0%;   opacity: 0; }
  10%  { opacity: 1; }
  90%  { opacity: 1; }
  100% { offset-distance: 100%; opacity: 0; }
}

/* Magnetic Pull Depth — hover */
.roycss-hover-magnetic-pull-2 {
  inline-size: 180px;
  block-size: 120px;
  border-radius: 20px;
  position: relative;
  background:
    linear-gradient(160deg, oklch(0.85 0.15 250), oklch(0.70 0.20 280));
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.4),
    0 10px 24px -8px oklch(0.4 0.15 270 / 0.5);
  transform-style: preserve-3d;
  perspective: 600px;
  transition:
    transform 0.5s cubic-bezier(0.2, 1.1, 0.3, 1),
    box-shadow 0.5s cubic-bezier(0.2, 1.1, 0.3, 1),
    filter 0.4s ease;
  cursor: pointer;
}
.roycss-hover-magnetic-pull-2::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(circle at 30% 20%, oklch(1 0 0 / 0.4), transparent 50%);
  pointer-events: none;
}
.roycss-hover-magnetic-pull-2::after {
  /* magnetic field lines */
  content: "";
  position: absolute;
  inset: -10%;
  border-radius: inherit;
  background:
    radial-gradient(circle at 50% 50%, oklch(0.80 0.20 280 / 0.4), transparent 60%);
  filter: blur(12px);
  opacity: 0;
  transition: opacity 0.5s ease;
  pointer-events: none;
  z-index: -1;
}
.roycss-hover-magnetic-pull-2:hover {
  transform: translateY(-8px) translateZ(30px) scale(1.04);
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.55),
    0 22px 50px -12px oklch(0.4 0.18 290 / 0.6),
    0 0 0 1px oklch(0.80 0.20 280 / 0.3);
  filter: saturate(1.15) brightness(1.05);
}
.roycss-hover-magnetic-pull-2:hover::after {
  opacity: 1;
  animation: roy-b16-magnetic-field 1.2s ease-in-out infinite;
}
@keyframes roy-b16-magnetic-field {
  0%, 100% { transform: scale(1);   opacity: 0.6; }
  50%      { transform: scale(1.15); opacity: 1; }
}

/* Glass Shatter Hover */
.roycss-hover-glass-shatter {
  inline-size: 200px;
  block-size: 140px;
  position: relative;
  border-radius: 16px;
  background:
    linear-gradient(135deg, oklch(0.95 0.06 220 / 0.25), oklch(0.85 0.10 280 / 0.18));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid oklch(1 0 0 / 0.3);
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.4),
    0 14px 30px -10px oklch(0.3 0.10 260 / 0.5);
  overflow: hidden;
  isolation: isolate;
  cursor: pointer;
  transition: transform 0.4s ease;
}
/* shard layer */
.roycss-hover-glass-shatter::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    conic-gradient(from 45deg at 50% 50%,
      oklch(1 0 0 / 0.18) 0deg,
      oklch(0.85 0.10 280 / 0.2) 90deg,
      oklch(1 0 0 / 0.12) 180deg,
      oklch(0.85 0.10 200 / 0.2) 270deg,
      oklch(1 0 0 / 0.18) 360deg);
  clip-path: polygon(0 0, 50% 0, 50% 50%, 0 50%, 0 0, 50% 50%, 100% 0, 100% 50%, 50% 50%, 50% 100%, 0 100%, 50% 50%, 100% 50%, 100% 100%, 50% 100%);
  transition:
    clip-path 0.6s cubic-bezier(0.4, 0, 0.2, 1),
    transform 0.6s cubic-bezier(0.4, 0, 0.2, 1),
    opacity 0.6s ease;
  pointer-events: none;
}
/* crack lines */
.roycss-hover-glass-shatter::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(45deg, transparent 49.4%, oklch(1 0 0 / 0.5) 49.7%, oklch(1 0 0 / 0.5) 50.3%, transparent 50.6%),
    linear-gradient(-45deg, transparent 49.4%, oklch(1 0 0 / 0.4) 49.7%, oklch(1 0 0 / 0.4) 50.3%, transparent 50.6%);
  background-size: 50% 50%, 50% 50%;
  background-position: 50% 50%;
  background-repeat: no-repeat;
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}
.roycss-hover-glass-shatter:hover {
  transform: scale(1.02);
}
.roycss-hover-glass-shatter:hover::before {
  clip-path: polygon(
    0 0, 30% -5%, 35% 35%, -5% 30%,
    0 0,
    40% 45%, 105% -5%, 95% 40%, 50% 50%,
    50% 105%, -5% 95%, 45% 55%,
    55% 50%, 105% 60%, 95% 105%, 50% 95%
  );
  transform: scale(1.08);
  opacity: 0.3;
  animation: roy-b16-shatter-drift 0.8s ease-out forwards;
}
.roycss-hover-glass-shatter:hover::after {
  opacity: 1;
}
@keyframes roy-b16-shatter-drift {
  0%   { transform: scale(1) translate(0,0); }
  100% { transform: scale(1.08) translate(2px, 2px); }
}

/* Liquid Morph Hover */
.roycss-hover-liquid-morph {
  inline-size: 160px;
  block-size: 64px;
  border: none;
  border-radius: 32px;
  position: relative;
  background:
    linear-gradient(135deg, oklch(0.80 0.22 200), oklch(0.65 0.24 240));
  color: oklch(0.98 0.02 240);
  font: 700 18px / 1 system-ui, sans-serif;
  letter-spacing: 0.04em;
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.4),
    0 12px 24px -8px oklch(0.4 0.18 220 / 0.5);
  cursor: pointer;
  overflow: hidden;
  isolation: isolate;
  transition:
    border-radius 0.7s cubic-bezier(0.3, 1.2, 0.4, 1),
    transform 0.5s cubic-bezier(0.3, 1.2, 0.4, 1),
    box-shadow 0.5s ease,
    filter 0.4s ease;
}
.roycss-hover-liquid-morph::before {
  /* liquid ripple layer */
  content: "";
  position: absolute;
  inset: -20%;
  background:
    radial-gradient(circle at 30% 50%, oklch(1 0 0 / 0.35), transparent 40%),
    radial-gradient(circle at 70% 50%, oklch(0.85 0.20 280 / 0.4), transparent 40%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}
.roycss-hover-liquid-morph::after {
  /* wobble blob deformation on hover */
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px oklch(1 0 0 / 0.2);
  pointer-events: none;
}
.roycss-hover-liquid-morph:hover {
  border-radius: 60% 40% 55% 45% / 55% 50% 50% 45%;
  transform: scale(1.06);
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.55),
    0 18px 36px -10px oklch(0.4 0.20 230 / 0.6);
  filter: saturate(1.2);
  animation: roy-b16-liquid-wobble 1.6s ease-in-out infinite;
}
.roycss-hover-liquid-morph:hover::before {
  opacity: 1;
  animation: roy-b16-liquid-ripple 1.6s ease-in-out infinite;
}
@keyframes roy-b16-liquid-wobble {
  0%, 100% { border-radius: 60% 40% 55% 45% / 55% 50% 50% 45%; }
  33%      { border-radius: 45% 55% 40% 60% / 60% 45% 55% 40%; }
  66%      { border-radius: 55% 45% 60% 40% / 40% 60% 45% 55%; }
}
@keyframes roy-b16-liquid-ripple {
  0%, 100% { transform: translate(0, 0) rotate(0deg); }
  50%      { transform: translate(4%, -3%) rotate(8deg); }
}

/* Leaf Fall Spiral */
.roycss-leaf-fall-spiral {
  width: 28px;
  height: 28px;
  background:
    radial-gradient(ellipse at 30% 30%,
      oklch(0.78 0.22 130) 0%,
      oklch(0.55 0.25 140) 60%,
      oklch(0.35 0.2 145) 100%);
  border-radius: 0 100% 0 100%;
  transform-origin: center;
  box-shadow:
    inset -2px -2px 4px oklch(0.3 0.15 140 / 0.5),
    0 2px 6px oklch(0.3 0.1 140 / 0.3);
  position: relative;
  top: 0;
  animation: roy-leaf-spiral 5.5s linear infinite;
}
@keyframes roy-leaf-spiral {
  0% {
    transform: translate(0, 0) rotate(0deg) scale(1);
    opacity: 0;
  }
  8% { opacity: 1; }
  20% {
    transform: translate(35px, 18px) rotate(140deg) scale(0.96);
  }
  40% {
    transform: translate(-25px, 38px) rotate(280deg) scale(0.92);
  }
  60% {
    transform: translate(30px, 58px) rotate(420deg) scale(0.88);
  }
  80% {
    transform: translate(-20px, 78px) rotate(560deg) scale(0.84);
  }
  92% { opacity: 1; }
  100% {
    transform: translate(0, 100px) rotate(720deg) scale(0.8);
    opacity: 0;
  }
}

/* Water Ripple Expand */
.roycss-water-ripple-expand {
  position: relative;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: radial-gradient(circle,
    oklch(0.7 0.18 220 / 0.65) 0%,
    oklch(0.5 0.22 240 / 0.35) 60%,
    oklch(0.3 0.15 250 / 0.15) 100%);
  box-shadow:
    inset 0 0 20px oklch(0.85 0.15 200 / 0.4),
    0 0 30px oklch(0.5 0.2 230 / 0.3);
}
.roycss-water-ripple-expand::before,
.roycss-water-ripple-expand::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 2px solid oklch(0.8 0.18 210 / 0.7);
  border-radius: 50%;
  animation: roy-ripple-out 2.4s ease-out infinite;
}
.roycss-water-ripple-expand::after {
  animation-delay: 1.2s;
}
@keyframes roy-ripple-out {
  0% {
    transform: scale(1);
    opacity: 1;
    border-width: 3px;
  }
  60% { opacity: 0.5; }
  100% {
    transform: scale(3.2);
    opacity: 0;
    border-width: 1px;
  }
}

/* Wind Sway Organic */
.roycss-wind-sway-organic {
  width: 36px;
  height: 90px;
  background: linear-gradient(180deg,
    oklch(0.55 0.25 140) 0%,
    oklch(0.4 0.22 135) 50%,
    oklch(0.3 0.18 130) 100%);
  border-radius: 50% 50% 6px 6px / 75% 75% 6px 6px;
  transform-origin: bottom center;
  box-shadow:
    inset -3px 0 6px oklch(0.2 0.1 130 / 0.4),
    inset 3px 0 4px oklch(0.7 0.2 140 / 0.3),
    0 4px 12px oklch(0.2 0.1 130 / 0.3);
  animation: roy-wind-sway 3.4s ease-in-out infinite;
}
.roycss-wind-sway-organic::before {
  content: "";
  position: absolute;
  top: -8px;
  left: 50%;
  transform: translateX(-50%);
  width: 18px;
  height: 18px;
  background: radial-gradient(circle at 35% 35%,
    oklch(0.85 0.28 350),
    oklch(0.6 0.3 10) 70%,
    oklch(0.4 0.25 15));
  border-radius: 50%;
  box-shadow: 0 0 12px oklch(0.7 0.3 350 / 0.6);
}
@keyframes roy-wind-sway {
  0%, 100% { transform: rotate(-5deg) skewX(-2deg); }
  25% { transform: rotate(7deg) skewX(3deg); }
  45% { transform: rotate(-3deg) skewX(-1deg); }
  70% { transform: rotate(6deg) skewX(2deg); }
  85% { transform: rotate(-2deg) skewX(-1deg); }
}

/* Scroll Cinematic Zoom — uses scroll-driven animations */
.roycss-scroll-cinematic-zoom {
  background:
    radial-gradient(circle at 50% 50%,
      oklch(0.55 0.28 290),
      oklch(0.3 0.2 300) 60%,
      oklch(0.1 0.1 310) 100%);
  border-radius: 1rem;
  border: 1px solid oklch(0.7 0.2 290 / 0.3);
  box-shadow:
    0 20px 60px oklch(0.2 0.15 300 / 0.5),
    inset 0 1px 0 oklch(1 0 0 / 0.15);
  animation: roy-cinematic-zoom linear both;
  animation-timeline: view();
  animation-range: entry 0% cover 50%;
}
@keyframes roy-cinematic-zoom {
  0% {
    transform: scale(0.6);
    opacity: 0;
    filter: blur(24px) saturate(0.6);
  }
  40% {
    transform: scale(0.85);
    opacity: 0.7;
    filter: blur(8px) saturate(0.85);
  }
  100% {
    transform: scale(1);
    opacity: 1;
    filter: blur(0) saturate(1);
  }
}
@supports not (animation-timeline: view()) {
  .roycss-scroll-cinematic-zoom {
    animation: roy-cinematic-fallback 4s ease-in-out infinite alternate;
  }
  @keyframes roy-cinematic-fallback {
    0% { transform: scale(0.85); opacity: 0.7; filter: blur(6px); }
    100% { transform: scale(1); opacity: 1; filter: blur(0); }
  }
}

/* Ambient Pulse Live */
.roycss-ambient-pulse-live {
  background: radial-gradient(circle at 35% 35%,
    oklch(0.85 0.22 25),
    oklch(0.6 0.28 15) 60%,
    oklch(0.4 0.25 10));
  border-radius: 50%;
  box-shadow:
    0 0 0 0 oklch(0.75 0.28 20 / 0.6),
    inset 0 0 20px oklch(0.95 0.15 30 / 0.5);
  position: relative;
  animation: roy-ambient-core 2s ease-in-out infinite;
}
.roycss-ambient-pulse-live::before,
.roycss-ambient-pulse-live::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid oklch(0.75 0.28 20 / 0.6);
  animation: roy-ambient-pulse 2.4s ease-out infinite;
}
.roycss-ambient-pulse-live::after {
  animation-delay: 1.2s;
}
@keyframes roy-ambient-pulse {
  0% {
    transform: scale(1);
    opacity: 1;
    border-width: 3px;
  }
  100% {
    transform: scale(2.6);
    opacity: 0;
    border-width: 1px;
  }
}
@keyframes roy-ambient-core {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.25); }
}

/* Haptic Bump */
.roycss-haptic-bump {
  background: linear-gradient(180deg,
    oklch(0.7 0.18 250),
    oklch(0.55 0.2 250));
  border-radius: 0.6rem;
  box-shadow:
    0 4px 12px oklch(0.3 0.1 250 / 0.3),
    inset 0 1px 0 oklch(1 0 0 / 0.4);
  animation: roy-haptic-bump 2.6s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
@keyframes roy-haptic-bump {
  0%, 88%, 100% { transform: translate(0, 0); }
  90% { transform: translate(2px, -3px); }
  92% { transform: translate(-2px, 2px); }
  94% { transform: translate(2px, -1px); }
  96% { transform: translate(-1px, 1px); }
  98% { transform: translate(1px, 0); }
}

/* Data Flow Stream */
.roycss-data-flow-stream {
  background:
    repeating-linear-gradient(90deg,
      oklch(0.65 0.28 180) 0,
      oklch(0.65 0.28 180) 12px,
      transparent 12px,
      transparent 32px),
    linear-gradient(90deg,
      oklch(0.1 0.05 200),
      oklch(0.15 0.1 195));
  background-size: 32px 100%, 100% 100%;
  background-repeat: repeat-x, no-repeat;
  border-radius: 0.5rem;
  border: 1px solid oklch(0.4 0.2 180 / 0.4);
  box-shadow:
    0 0 20px oklch(0.5 0.25 180 / 0.4),
    inset 0 0 12px oklch(0.4 0.2 180 / 0.3);
  animation: roy-data-flow 0.9s linear infinite;
}
@keyframes roy-data-flow {
  from { background-position: 0 0, 0 0; }
  to { background-position: 32px 0, 0 0; }
}

/* Breathing Gradient */
.roycss-breathing-gradient {
  background: linear-gradient(135deg,
    oklch(0.55 0.28 280),
    oklch(0.55 0.28 200),
    oklch(0.55 0.28 320),
    oklch(0.55 0.28 30));
  background-size: 250% 250%;
  border-radius: 1rem;
  box-shadow:
    0 12px 36px oklch(0.3 0.2 280 / 0.4),
    inset 0 1px 0 oklch(1 0 0 / 0.3);
  animation: roy-grad-breathe 8s ease-in-out infinite;
}
@keyframes roy-grad-breathe {
  0%, 100% {
    background-position: 0% 50%;
    filter: hue-rotate(0deg) brightness(1) saturate(1);
  }
  50% {
    background-position: 100% 50%;
    filter: hue-rotate(60deg) brightness(1.15) saturate(1.2);
  }
}

/* Satisfying Checkmark */
.roycss-micro-satisfying-check {
  position: relative;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%,
    oklch(0.85 0.25 150),
    oklch(0.55 0.3 155));
  box-shadow:
    0 8px 20px oklch(0.3 0.2 150 / 0.4),
    inset 0 2px 4px oklch(1 0 0 / 0.4),
    inset 0 -3px 6px oklch(0.3 0.15 150 / 0.4);
  animation: roy-check-pop 2.4s ease-in-out infinite;
}
.roycss-micro-satisfying-check::before {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  width: 26px;
  height: 13px;
  transform: translate(-50%, -65%) rotate(-45deg);
  border-inline-end: 4px solid oklch(0.98 0.05 150);
  border-block-end: 4px solid oklch(0.98 0.05 150);
  border-end-end-radius: 2px;
  transform-origin: center;
  filter: drop-shadow(0 1px 2px oklch(0 0 0 / 0.3));
  animation: roy-check-draw 2.4s cubic-bezier(0.65, 0, 0.35, 1) infinite;
}
@keyframes roy-check-pop {
  0%, 40% {
    transform: scale(0.85);
    filter: brightness(0.9);
  }
  50% {
    transform: scale(1.15);
    filter: brightness(1.2);
  }
  60% {
    transform: scale(0.95);
  }
  70% {
    transform: scale(1.02);
  }
  80%, 100% {
    transform: scale(1);
    filter: brightness(1);
  }
}
@keyframes roy-check-draw {
  0%, 40% {
    width: 0;
    height: 0;
    opacity: 0;
  }
  50% {
    width: 8px;
    height: 4px;
    opacity: 1;
  }
  65% {
    width: 30px;
    height: 15px;
    opacity: 1;
  }
  75% {
    width: 24px;
    height: 12px;
  }
  85%, 100% {
    width: 26px;
    height: 13px;
    opacity: 1;
  }
}

/* Liquid Toggle — checkbox driven */
.roycss-micro-toggle-liquid {
  position: relative;
  display: inline-block;
  width: 70px;
  height: 36px;
  border-radius: 18px;
  background: oklch(0.3 0.05 250);
  box-shadow:
    inset 0 4px 8px oklch(0 0 0 / 0.3),
    inset 0 -2px 4px oklch(1 0 0 / 0.05),
    0 2px 8px oklch(0 0 0 / 0.2);
  cursor: pointer;
  transition: background 0.5s cubic-bezier(0.65, 0, 0.35, 1);
}
.roycss-micro-toggle-liquid::before {
  content: "";
  position: absolute;
  inset-block-start: 4px;
  inset-inline-start: 4px;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: linear-gradient(135deg,
    oklch(0.95 0.05 0),
    oklch(0.7 0.2 25));
  box-shadow:
    0 2px 6px oklch(0 0 0 / 0.3),
    inset 0 1px 0 oklch(1 0 0 / 0.5);
  transition: transform 0.5s cubic-bezier(0.68, -0.55, 0.27, 1.55),
              border-radius 0.4s ease,
              background 0.4s ease;
  animation: roy-liquid-idle 2s ease-in-out infinite;
}
.roycss-micro-toggle-liquid:hover::before {
  border-radius: 30% 70% 70% 30% / 50%;
  transform: translateX(2px) scale(1.05);
}
.roycss-micro-toggle-liquid:active::before {
  border-radius: 50% 50% 30% 70% / 60% 40%;
  transform: translateX(15px) scale(1.1);
  background: linear-gradient(135deg,
    oklch(0.85 0.2 150),
    oklch(0.6 0.25 160));
}
@keyframes roy-liquid-idle {
  0%, 100% { border-radius: 50%; }
  50% { border-radius: 45% 55% 50% 50% / 50% 50% 55% 45%; }
}
.roycss-micro-toggle-liquid:active {
  background: oklch(0.4 0.2 150);
}

/* Pull to Refresh — animated indicator */
.roycss-micro-pull-refresh {
  position: relative;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg,
    oklch(0.7 0.2 250),
    oklch(0.55 0.22 250));
  box-shadow:
    0 6px 16px oklch(0.3 0.1 250 / 0.35),
    inset 0 1px 0 oklch(1 0 0 / 0.4),
    inset 0 -2px 4px oklch(0.3 0.1 250 / 0.3);
  animation: roy-pull-cycle 3s cubic-bezier(0.34, 1.56, 0.64, 1) infinite;
}
.roycss-micro-pull-refresh::before {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  border: 3px solid oklch(0.95 0.05 250);
  border-block-start-color: transparent;
  border-inline-end-color: transparent;
  animation: roy-pull-spin 0.8s linear infinite;
  animation-delay: 1.2s;
  opacity: 0;
}
.roycss-micro-pull-refresh::after {
  content: "";
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  width: 10px;
  height: 10px;
  transform: translate(-50%, -75%) rotate(45deg);
  border-inline-end: 3px solid oklch(0.95 0.05 250);
  border-block-end: 3px solid oklch(0.95 0.05 250);
  opacity: 1;
  animation: roy-pull-arrow 3s ease-in-out infinite;
}
@keyframes roy-pull-cycle {
  0%, 100% {
    transform: translateY(-20px) scale(0.6);
    filter: brightness(0.9);
